import {
  Container,
  Typography,
  Grid,
  Card,
  CardContent,
  CardMedia,
  Button,
  Box,
  Icon,
} from "@mui/material";

import {
  useEffect,
  useState,
} from "react";

import ArrowBackIcon from "@mui/icons-material/ArrowBack";

import API from "../services/api";


import {
  Link,
  useNavigate,
} from "react-router-dom";

export default function RecycleBin() {

  const [blogs, setBlogs] =
    useState([]);

  const fetchDeletedBlogs =
    async () => {

      try {

        const response =
          await API.get(
            "/blogs/deleted"
          );

        setBlogs(response.data);

      } catch (error) {

        console.log(error);
      }
    };

  useEffect(() => {

    fetchDeletedBlogs();

  }, []);

  const handleRestore =
    async (id) => {

      try {

        await API.put(
          `/blogs/restore/${id}`
        );

        fetchDeletedBlogs();

      } catch (error) {

        console.log(error);
      }
    };

  const handlePermanentDelete =
    async (id) => {

      const confirmDelete =
        window.confirm(
          "Delete permanently?"
        );

      if (!confirmDelete) return;

      try {

        await API.delete(
          `/blogs/permanent/${id}`
        );

        fetchDeletedBlogs();

      } catch (error) {

        console.log(error);
      }
    };

  return (

    <Container sx={{ py: 5 }}>

<IconButton
      onClick={() => navigate("/")}
      sx={{
        width: 55,
        height: 55,
        background:
          "linear-gradient(135deg, #2563eb, #7c3aed)",
        color: "white",
        boxShadow: 4,

        "&:hover": {
          transform: "scale(1.08)",
          background:
            "linear-gradient(135deg, #1d4ed8, #6d28d9)",
        },

        transition: "0.3s",
      }}
    >
      <ArrowBackIcon />
    </IconButton>
      <Typography

        variant="h4"
        fontWeight={700}
        gutterBottom
      >
        Recycle Bin
      </Typography>

      {blogs.length === 0 ? (
        <Box
          sx={{
            textAlign: "center",
            mt: 10,
          }}
        >
          <Typography
            variant="h5"
            fontWeight={700}
            gutterBottom
          >
            Recycle Bin is empty!
          </Typography>
          <Typography color="text.secondary">
            Your deleted blogs will be shown here!
          </Typography>
        </Box>
      ) : (
        <Grid container spacing={4}>
          {blogs.map((blog) => (
            <Grid
              item
              xs={12}
              sm={6}
              md={4}
              key={blog._id}
            >
              <Card>
                <CardMedia
                  component="img"
                  height="200"
                  image={blog.image}
                />
                <CardContent>
                  <Typography
                    variant="h6"
                    gutterBottom
                  >
                    {blog.title}
                  </Typography>
                  <Box
                    sx={{
                      display: "flex",
                      gap: 1,
                      mt: 2,
                    }}
                  >
                    <Button
                      variant="contained"
                      onClick={() =>
                        handleRestore(
                          blog._id
                        )
                      }
                    >
                      Restore
                    </Button>
                    <Button
                      variant="outlined"
                      color="error"
                      onClick={() =>
                        handlePermanentDelete(
                          blog._id
                        )
                      }
                    >
                      Delete
                    </Button>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      )}

    </Container>
  );
}
